1	#include <string.h>
2	#include <stdlib.h>
3	#include <ctype.h>
4	#include <stdio.h>
5	#include "lexer.h"
6	#include "error.h"
7	
8	void lexer_init(Lexer *l, const char *source) {
9	    l->src  = source;
10	    l->pos  = 0;
11	    l->line = 1;
12	    l->col  = 1;
13	}
14	
15	/* ------------------------------------------------------------------ helpers */
16	
17	static char peek_c(const Lexer *l)          { return l->src[l->pos]; }
18	static char peek2_c(const Lexer *l)         { return l->src[l->pos] ? l->src[l->pos + 1] : '\0'; }
19	
20	static char advance_c(Lexer *l) {
21	    char c = l->src[l->pos++];
22	    if (c == '\n') { l->line++; l->col = 1; }
23	    else            { l->col++; }
24	    return c;
25	}
26	
27	static Token make_tok(TokenType t, const char *start, int length, int line, int col) {
28	    Token tok;
29	    tok.type    = t;
30	    tok.start   = start;
31	    tok.length  = length;
32	    tok.line    = line;
33	    tok.col     = col;
34	    tok.num_val = 0.0;
35	    return tok;
36	}
37	
38	/* ------------------------------------------------------------------ keyword table */
39	
40	static const struct { const char *word; TokenType type; } KEYWORDS[] = {
41	    { "let",      TOK_LET      },
42	    { "function", TOK_FUNCTION },
43	    { "return",   TOK_RETURN   },
44	    { "for",      TOK_FOR      },
45	    { "in",       TOK_IN       },
46	    { "if",       TOK_IF       },
47	    { "elif",     TOK_ELIF     },
48	    { "else",     TOK_ELSE     },
49	    { "print",    TOK_PRINT    },
50	    { NULL,       TOK_ERROR    },
51	};
52	
53	static TokenType check_keyword(const char *start, int len) {
54	    for (int i = 0; KEYWORDS[i].word; i++) {
55	        if ((int)strlen(KEYWORDS[i].word) == len &&
56	            memcmp(KEYWORDS[i].word, start, (size_t)len) == 0) {
57	            return KEYWORDS[i].type;
58	        }
59	    }
60	    return TOK_IDENT;
61	}
62	
63	/* ------------------------------------------------------------------ unit literal probe
64	   Returns the length (4, 5, or 6) if src[pos..] starts with a compound unit,
65	   0 otherwise.  Called before consuming '/'. */
66	
67	static int probe_unit_literal(const Lexer *l) {
68	    const char *s = l->src + l->pos;
69	    if (strncmp(s, "g/mol",  5) == 0 && !isalpha((unsigned char)s[5])) return 5;
70	    if (strncmp(s, "kg/mol", 6) == 0 && !isalpha((unsigned char)s[6])) return 6;
71	    if (strncmp(s, "kJ/mol", 6) == 0 && !isalpha((unsigned char)s[6])) return 6;
72	    return 0;
73	}
74	
75	/* ------------------------------------------------------------------ scan string */
76	
77	static Token scan_string(Lexer *l) {
78	    int start_line = l->line, start_col = l->col;
79	    const char *start = l->src + l->pos - 1; /* opening '"' already consumed */
80	    while (peek_c(l) && peek_c(l) != '"' && peek_c(l) != '\n') {
81	        if (peek_c(l) == '\\') advance_c(l);
82	        advance_c(l);
83	    }
84	    if (peek_c(l) != '"') {
85	        error_at(start_line, start_col, "unterminated string literal");
86	        return make_tok(TOK_ERROR, start, 1, start_line, start_col);
87	    }
88	    advance_c(l); /* closing '"' */
89	    int len = (int)(l->src + l->pos - start);
90	    return make_tok(TOK_STRING, start, len, start_line, start_col);
91	}
92	
93	/* ------------------------------------------------------------------ scan char */
94	
95	static Token scan_char(Lexer *l) {
96	    int start_line = l->line, start_col = l->col;
97	    const char *start = l->src + l->pos - 1;
98	    if (peek_c(l) == '\\') advance_c(l);
99	    if (peek_c(l) && peek_c(l) != '\'') advance_c(l);
100	    if (peek_c(l) != '\'') {
101	        error_at(start_line, start_col, "unterminated character literal");
102	        return make_tok(TOK_ERROR, start, 1, start_line, start_col);
103	    }
104	    advance_c(l);
105	    int len = (int)(l->src + l->pos - start);
106	    return make_tok(TOK_CHAR, start, len, start_line, start_col);
107	}
108	
109	/* ------------------------------------------------------------------ scan number */
110	
111	static Token scan_number(Lexer *l, const char *start, int start_line, int start_col) {
112	    while (isdigit((unsigned char)peek_c(l))) advance_c(l);
113	    if (peek_c(l) == '.' && isdigit((unsigned char)peek2_c(l))) {
114	        advance_c(l);
115	        while (isdigit((unsigned char)peek_c(l))) advance_c(l);
116	    }
117	    if (peek_c(l) == 'e' || peek_c(l) == 'E') {
118	        advance_c(l);
119	        if (peek_c(l) == '+' || peek_c(l) == '-') advance_c(l);
120	        while (isdigit((unsigned char)peek_c(l))) advance_c(l);
121	    }
122	    int len = (int)(l->src + l->pos - start);
123	    Token tok = make_tok(TOK_NUMBER, start, len, start_line, start_col);
124	    tok.num_val = strtod(start, NULL);
125	    return tok;
126	}
127	
128	/* ------------------------------------------------------------------ scan ident/keyword */
129	
130	static Token scan_ident(Lexer *l, const char *start, int start_line, int start_col) {
131	    while (isalnum((unsigned char)peek_c(l)) || peek_c(l) == '_') advance_c(l);
132	    int len = (int)(l->src + l->pos - start);
133	    TokenType t = check_keyword(start, len);
134	    return make_tok(t, start, len, start_line, start_col);
135	}
136	
137	/* ------------------------------------------------------------------ scan formula */
138	
139	static Token scan_formula(Lexer *l, const char *start, int start_line, int start_col) {
140	    /* already consumed first uppercase letter; continue */
141	    if (islower((unsigned char)peek_c(l))) advance_c(l); /* optional lowercase */
142	    while (isdigit((unsigned char)peek_c(l))) advance_c(l); /* optional digits */
143	    /* additional element groups */
144	    while (isupper((unsigned char)peek_c(l))) {
145	        advance_c(l);
146	        if (islower((unsigned char)peek_c(l))) advance_c(l);
