1	#include <string.h>
2	#include <stdio.h>
3	#include "parser.h"
4	#include "error.h"
5	
6	/* ================================================================
7	   Helpers
8	   ================================================================ */
9	
10	static int tok_is(const Token *t, TokenType type) {
11	    return t->type == type;
12	}
13	
14	/* Test if current token is an IDENT with a specific lexeme. */
15	static int ident_is(const Token *t, const char *word) {
16	    if (t->type != TOK_IDENT) return 0;
17	    return (int)strlen(word) == t->length && memcmp(t->start, word, (size_t)t->length) == 0;
18	}
19	
20	static void advance(Parser *p) {
21	    p->previous = p->current;
22	    p->current  = lexer_next(p->lexer);
23	}
24	
25	/* Consume and return previous; crash if type doesn't match. */
26	static Token expect(Parser *p, TokenType type) {
27	    if (!tok_is(&p->current, type)) {
28	        error_at(p->current.line, p->current.col,
29	                 "expected %s but got %.*s",
30	                 token_type_name(type),
31	                 p->current.length, p->current.start);
32	        /* panic-mode recovery: skip to next sync point */
33	        while (!tok_is(&p->current, TOK_SEMICOLON) &&
34	               !tok_is(&p->current, TOK_RBRACE)    &&
35	               !tok_is(&p->current, TOK_EOF)) {
36	            advance(p);
37	        }
38	    }
39	    Token t = p->current;
40	    advance(p);
41	    return t;
42	}
43	
44	/* Consume and return previous; crash if ident lexeme doesn't match. */
45	static Token expect_ident(Parser *p, const char *word) {
46	    if (!ident_is(&p->current, word)) {
47	        error_at(p->current.line, p->current.col,
48	                 "expected '%s' but got %.*s",
49	                 word, p->current.length, p->current.start);
50	    }
51	    Token t = p->current;
52	    advance(p);
53	    return t;
54	}
55	
56	static int check(const Parser *p, TokenType type) {
57	    return tok_is(&p->current, type);
58	}
59	
60	static int match(Parser *p, TokenType type) {
61	    if (!check(p, type)) return 0;
62	    advance(p);
63	    return 1;
64	}
65	
66	/* ================================================================
67	   Contextual keyword helpers
68	   ================================================================ */
69	
70	static int is_unit(const Parser *p) {
71	    return tok_is(&p->current, TOK_UNIT_LIT) ||
72	           ident_is(&p->current, "mol") ||
73	           ident_is(&p->current, "g")   ||
74	           ident_is(&p->current, "kg")  ||
75	           ident_is(&p->current, "kJ");
76	}
77	
78	static int is_type_name(const Parser *p) {
79	    return ident_is(&p->current, "element")  ||
80	           ident_is(&p->current, "compound") ||
81	           ident_is(&p->current, "reaction");
82	}
