92	/* ================================================================
93	   §10  Expressions
94	   ================================================================ */
95	
96	static AstNode *parse_primary(Parser *p) {
97	    Token t = p->current;
98	
99	    /* number — may be followed by a unit → quantity */
100	    if (check(p, TOK_NUMBER)) {
101	        advance(p);
102	        AstNode *num = ast_new(ND_NUMBER, t.line);
103	        num->num = t.num_val;
104	        ast_set_text(num, t.start, t.length);
105	
106	        if (is_unit(p)) {
107	            Token unit = p->current;
108	            advance(p);
109	            AstNode *q = ast_new(ND_QUANTITY, t.line);
110	            ast_set_text(q, unit.start, unit.length);
111	            ast_add_child(q, num);
112	            return q;
113	        }
114	        return num;
115	    }
116	
117	    if (check(p, TOK_STRING)) {
118	        advance(p);
119	        AstNode *n = ast_new(ND_STRING, t.line);
120	        ast_set_text(n, t.start, t.length);
121	        return n;
122	    }
123	
124	    if (check(p, TOK_CHAR)) {
125	        advance(p);
126	        AstNode *n = ast_new(ND_CHAR, t.line);
127	        ast_set_text(n, t.start, t.length);
128	        return n;
129	    }
130	
131	    if (check(p, TOK_FORMULA)) {
132	        advance(p);
133	        AstNode *n = ast_new(ND_FORMULA, t.line);
134	        ast_set_text(n, t.start, t.length);
135	        return n;
136	    }
137	
138	    /* list literal */
139	    if (check(p, TOK_LBRACKET)) {
140	        advance(p);
141	        AstNode *list = ast_new(ND_LIST, t.line);
142	        if (!check(p, TOK_RBRACKET)) {
143	            ast_add_child(list, parse_expression(p));
144	            while (match(p, TOK_COMMA)) {
145	                if (check(p, TOK_RBRACKET)) break;
146	                ast_add_child(list, parse_expression(p));
147	            }
148	        }
149	        expect(p, TOK_RBRACKET);
150	        return list;
151	    }
152	
153	    /* parenthesised expression */
154	    if (check(p, TOK_LPAREN)) {
155	        advance(p);
156	        AstNode *inner = parse_expression(p);
157	        expect(p, TOK_RPAREN);
158	        return inner;
159	    }
160	
161	    /* identifier */
162	    if (check(p, TOK_IDENT)) {
163	        advance(p);
164	        AstNode *n = ast_new(ND_IDENT, t.line);
165	        ast_set_text(n, t.start, t.length);
166	        return n;
167	    }
168	
169	    error_at(t.line, t.col, "unexpected token %.*s in expression",
170	             t.length, t.start);
171	    advance(p);
172	    AstNode *err = ast_new(ND_IDENT, t.line);
173	    ast_set_text(err, "?", 1);
174	    return err;
175	}
176	
177	static AstNode *parse_postfix(Parser *p) {
178	    AstNode *node = parse_primary(p);
179	
180	    for (;;) {
181	        if (check(p, TOK_DOT)) {
182	            advance(p);
183	            Token member = p->current;
184	            expect(p, TOK_IDENT);
185	            AstNode *m = ast_new(ND_MEMBER, member.line);
186	            ast_set_text(m, member.start, member.length);
187	            ast_add_child(m, node);
188	            node = m;
189	        } else if (check(p, TOK_LBRACKET)) {
190	            advance(p);
191	            AstNode *idx = ast_new(ND_INDEX, p->current.line);
192	            ast_add_child(idx, node);
193	            ast_add_child(idx, parse_expression(p));
194	            expect(p, TOK_RBRACKET);
195	            node = idx;
196	        } else if (check(p, TOK_LPAREN)) {
197	            advance(p);
198	            AstNode *call = ast_new(ND_CALL, p->current.line);
199	            ast_add_child(call, node);
200	            if (!check(p, TOK_RPAREN)) {
201	                ast_add_child(call, parse_expression(p));
202	                while (match(p, TOK_COMMA)) {
203	                    ast_add_child(call, parse_expression(p));
204	                }
205	            }
206	            expect(p, TOK_RPAREN);
207	            node = call;
208	        } else {
209	            break;
210	        }
211	    }
212	    return node;
213	}
214	
215	static AstNode *parse_unary(Parser *p) {
216	    if (check(p, TOK_MINUS)) {
217	        Token t = p->current;
218	        advance(p);
219	        AstNode *n = ast_new(ND_UNARY, t.line);
220	        ast_set_text(n, "-", 1);
221	        ast_add_child(n, parse_postfix(p));
222	        return n;
223	    }
224	    return parse_postfix(p);
225	}
226	
227	static AstNode *parse_multiplicative(Parser *p) {
228	    AstNode *left = parse_unary(p);
229	    while (check(p, TOK_STAR) || check(p, TOK_SLASH)) {
230	        Token op = p->current;
231	        advance(p);
232	        AstNode *n = ast_new(ND_BINARY, op.line);
233	        ast_set_text(n, op.start, op.length);
234	        ast_add_child(n, left);
235	        ast_add_child(n, parse_unary(p));
236	        left = n;
237	    }
238	    return left;
239	}
240	
241	static AstNode *parse_additive(Parser *p) {
242	    AstNode *left = parse_multiplicative(p);
243	    while (check(p, TOK_PLUS) || check(p, TOK_MINUS)) {
244	        Token op = p->current;
245	        advance(p);
246	        AstNode *n = ast_new(ND_BINARY, op.line);
247	        ast_set_text(n, op.start, op.length);
248	        ast_add_child(n, left);
249	        ast_add_child(n, parse_multiplicative(p));
250	        left = n;
251	    }
252	    return left;
253	}
254	
255	static AstNode *parse_comparison(Parser *p) {
256	    AstNode *left = parse_additive(p);
257	    if (check(p, TOK_EQ_EQ)   || check(p, TOK_BANG_EQ) ||
258	        check(p, TOK_LT_EQ)   || check(p, TOK_GT_EQ)   ||
259	        check(p, TOK_LT)      || check(p, TOK_GT)) {
260	        Token op = p->current;
261	        advance(p);
262	        AstNode *n = ast_new(ND_BINARY, op.line);
263	        ast_set_text(n, op.start, op.length);
264	        ast_add_child(n, left);
265	        ast_add_child(n, parse_additive(p));
266	        return n;
267	    }
268	    return left;
269	}
270	
271	static AstNode *parse_expression(Parser *p) {
272	    return parse_comparison(p);
273	}
