275	/* ================================================================
276	   §9  Reaction sub-grammar
277	   ================================================================ */
278	
279	/* <reaction_term> → <species_ref> | <coefficient> "*" <species_ref> */
280	static AstNode *parse_reaction_term(Parser *p) {
281	    AstNode *term = ast_new(ND_REACTION_TERM, p->current.line);
282	
283	    /* coefficient? */
284	    if (check(p, TOK_NUMBER)) {
285	        Token coeff = p->current;
286	        advance(p);
287	        AstNode *c = ast_new(ND_NUMBER, coeff.line);
288	        c->num = coeff.num_val;
289	        ast_set_text(c, coeff.start, coeff.length);
290	
291	        if (match(p, TOK_STAR)) {
292	            /* species follows */
293	            AstNode *sp = ast_new(p->current.type == TOK_FORMULA ? ND_FORMULA : ND_IDENT,
294	                                  p->current.line);
295	            ast_set_text(sp, p->current.start, p->current.length);
296	            advance(p);
297	            ast_add_child(term, c);
298	            ast_add_child(term, sp);
299	        } else {
300	            /* bare number — treat as coefficient 1 with species = that number? */
301	            /* Actually this shouldn't happen per grammar; just return number */
302	            ast_add_child(term, c);
303	        }
304	        return term;
305	    }
306	
307	    /* bare species_ref */
308	    AstNode *sp = ast_new(check(p, TOK_FORMULA) ? ND_FORMULA : ND_IDENT,
309	                          p->current.line);
310	    ast_set_text(sp, p->current.start, p->current.length);
311	    advance(p);
312	    ast_add_child(term, sp);
313	    return term;
314	}
315	
316	/* <reaction_expression> → <reaction_term> { "+" <reaction_term> } */
317	static AstNode *parse_reaction_expression(Parser *p) {
318	    AstNode *rxn = ast_new(ND_REACTION_EXPR, p->current.line);
319	    ast_add_child(rxn, parse_reaction_term(p));
320	    while (check(p, TOK_PLUS)) {
321	        advance(p);
322	        ast_add_child(rxn, parse_reaction_term(p));
323	    }
324	    return rxn;
325	}
