327	/* ================================================================
328	   §8  Reaction declaration
329	   ================================================================ */
330	
331	static AstNode *parse_reaction_field(Parser *p) {
332	    AstNode *field = ast_new(ND_REACTION_FIELD, p->current.line);
333	
334	    if (ident_is(&p->current, "reactants")) {
335	        Token key = p->current; advance(p);
336	        ast_set_text(field, key.start, key.length);
337	        expect(p, TOK_EQ);
338	        ast_add_child(field, parse_reaction_expression(p));
339	    } else if (ident_is(&p->current, "products")) {
340	        Token key = p->current; advance(p);
341	        ast_set_text(field, key.start, key.length);
342	        expect(p, TOK_EQ);
343	        ast_add_child(field, parse_reaction_expression(p));
344	    } else if (ident_is(&p->current, "check")) {
345	        Token key = p->current; advance(p);
346	        ast_set_text(field, key.start, key.length);
347	        expect(p, TOK_EQ);
348	        Token val = expect_ident(p, "balanced");
349	        AstNode *v = ast_new(ND_IDENT, val.line);
350	        ast_set_text(v, val.start, val.length);
351	        ast_add_child(field, v);
352	    } else if (ident_is(&p->current, "energy")) {
353	        Token key = p->current; advance(p);
354	        ast_set_text(field, key.start, key.length);
355	        expect(p, TOK_EQ);
356	
357	        AstNode *energy = ast_new(ND_ENERGY_EXPR, p->current.line);
358	        if (ident_is(&p->current, "exothermic") || ident_is(&p->current, "endothermic")) {
359	            Token kind = p->current; advance(p);
360	            ast_set_text(energy, kind.start, kind.length);
361	        } else {
362	            error_at(p->current.line, p->current.col,
363	                     "expected 'exothermic' or 'endothermic'");
364	        }
365	        /* quantity: number + unit */
366	        Token num_tok = p->current;
367	        expect(p, TOK_NUMBER);
368	        AstNode *num = ast_new(ND_NUMBER, num_tok.line);
369	        num->num = num_tok.num_val;
370	        ast_set_text(num, num_tok.start, num_tok.length);
371	
372	        if (is_unit(p)) {
373	            Token unit = p->current; advance(p);
374	            AstNode *q = ast_new(ND_QUANTITY, num_tok.line);
375	            ast_set_text(q, unit.start, unit.length);
376	            ast_add_child(q, num);
377	            ast_add_child(energy, q);
378	        } else {
379	            ast_add_child(energy, num);
380	        }
381	        ast_add_child(field, energy);
382	    } else {
383	        error_at(p->current.line, p->current.col,
384	                 "unknown reaction field '%.*s'",
385	                 p->current.length, p->current.start);
386	        advance(p);
387	    }
388	    return field;
389	}
390	
391	static AstNode *parse_reaction_declaration(Parser *p) {
392	    Token kw = p->current;  /* "reaction" ident */
393	    advance(p);             /* consume "reaction" */
394	    AstNode *decl = ast_new(ND_REACTION_DECL, kw.line);
395	
396	    Token name = p->current;
397	    expect(p, TOK_IDENT);
398	    ast_set_text(decl, name.start, name.length);
399	
400	    expect(p, TOK_LBRACE);
401	    while (!check(p, TOK_RBRACE) && !check(p, TOK_EOF)) {
402	        ast_add_child(decl, parse_reaction_field(p));
403	        if (!match(p, TOK_COMMA)) break;
404	    }
405	    /* allow trailing comma */
406	    match(p, TOK_COMMA);
407	    expect(p, TOK_RBRACE);
408	    return decl;
409	}
410	
411	/* ================================================================
412	   §7  Compound declaration
413	   ================================================================ */
414	
415	static AstNode *parse_compound_declaration(Parser *p) {
416	    Token kw = p->current; advance(p);
417	    AstNode *decl = ast_new(ND_COMPOUND_DECL, kw.line);
418	
419	    Token name = p->current;
420	    expect(p, TOK_IDENT);
421	    ast_set_text(decl, name.start, name.length);
422	
423	    expect(p, TOK_LBRACE);
424	    while (!check(p, TOK_RBRACE) && !check(p, TOK_EOF)) {
425	        AstNode *field = ast_new(ND_COMPOUND_FIELD, p->current.line);
426	        if (ident_is(&p->current, "formula")) {
427	            Token key = p->current; advance(p);
428	            ast_set_text(field, key.start, key.length);
429	            expect(p, TOK_EQ);
430	            Token val = p->current;
431	            if (check(p, TOK_FORMULA)) {
432	                advance(p);
433	                AstNode *v = ast_new(ND_FORMULA, val.line);
434	                ast_set_text(v, val.start, val.length);
435	                ast_add_child(field, v);
436	            } else {
437	                error_at(val.line, val.col, "expected formula literal after 'formula ='");
438	                advance(p);
439	            }
440	        } else if (ident_is(&p->current, "name")) {
441	            Token key = p->current; advance(p);
442	            ast_set_text(field, key.start, key.length);
443	            expect(p, TOK_EQ);
444	            Token val = p->current;
445	            expect(p, TOK_STRING);
446	            AstNode *v = ast_new(ND_STRING, val.line);
447	            ast_set_text(v, val.start, val.length);
448	            ast_add_child(field, v);
449	        } else {
450	            error_at(p->current.line, p->current.col,
451	                     "unknown compound field '%.*s'",
452	                     p->current.length, p->current.start);
453	            advance(p);
454	        }
455	        ast_add_child(decl, field);
456	        if (!match(p, TOK_COMMA)) break;
457	    }
458	    match(p, TOK_COMMA);
459	    expect(p, TOK_RBRACE);
460	    return decl;
461	}
