463	/* ================================================================
464	   §6  Element declaration
465	   ================================================================ */
466	
467	static AstNode *parse_element_declaration(Parser *p) {
468	    Token kw = p->current; advance(p);
469	    AstNode *decl = ast_new(ND_ELEMENT_DECL, kw.line);
470	
471	    Token sym = p->current;
472	    /* element symbol is a FORMULA_LITERAL, e.g. H, O, C */
473	    if (!check(p, TOK_FORMULA)) {
474	        error_at(sym.line, sym.col,
475	                 "expected element symbol (formula literal) after 'element'");
476	    } else {
477	        advance(p);
478	    }
479	    ast_set_text(decl, sym.start, sym.length);
480	
481	    expect(p, TOK_LBRACE);
482	    while (!check(p, TOK_RBRACE) && !check(p, TOK_EOF)) {
483	        AstNode *field = ast_new(ND_ELEMENT_FIELD, p->current.line);
484	        if (ident_is(&p->current, "atomic_mass")) {
485	            Token key = p->current; advance(p);
486	            ast_set_text(field, key.start, key.length);
487	            expect(p, TOK_EQ);
488	            Token val = p->current;
489	            expect(p, TOK_NUMBER);
490	            AstNode *v = ast_new(ND_NUMBER, val.line);
491	            v->num = val.num_val;
492	            ast_set_text(v, val.start, val.length);
493	            ast_add_child(field, v);
494	        } else if (ident_is(&p->current, "valence")) {
495	            Token key = p->current; advance(p);
496	            ast_set_text(field, key.start, key.length);
497	            expect(p, TOK_EQ);
498	            Token val = p->current;
499	            expect(p, TOK_NUMBER);
500	            AstNode *v = ast_new(ND_NUMBER, val.line);
501	            v->num = val.num_val;
502	            ast_set_text(v, val.start, val.length);
503	            ast_add_child(field, v);
504	        } else if (ident_is(&p->current, "symbol")) {
505	            Token key = p->current; advance(p);
506	            ast_set_text(field, key.start, key.length);
507	            expect(p, TOK_EQ);
508	            Token val = p->current;
509	            expect(p, TOK_STRING);
510	            AstNode *v = ast_new(ND_STRING, val.line);
511	            ast_set_text(v, val.start, val.length);
512	            ast_add_child(field, v);
513	        } else {
514	            error_at(p->current.line, p->current.col,
515	                     "unknown element field '%.*s'",
516	                     p->current.length, p->current.start);
517	            advance(p);
518	        }
519	        ast_add_child(decl, field);
520	        if (!match(p, TOK_COMMA)) break;
521	    }
522	    match(p, TOK_COMMA);
523	    expect(p, TOK_RBRACE);
524	    return decl;
525	}
526	
527	/* ================================================================
528	   §3  Function declaration
529	   ================================================================ */
530	
531	static AstNode *parse_parameter(Parser *p) {
532	    AstNode *param = ast_new(ND_PARAM, p->current.line);
533	
534	    /* optional type annotation: element/compound/reaction before an ident */
535	    if (is_type_name(p) && p->current.type == TOK_IDENT) {
536	        /* look ahead: if next is IDENT, consume as type annotation */
537	        Token type_tok = p->current;
538	        advance(p);
539	        if (check(p, TOK_IDENT)) {
540	            /* type annotation confirmed */
541	            char type_str[64];
542	            int len = type_tok.length < 63 ? type_tok.length : 63;
543	            memcpy(type_str, type_tok.start, (size_t)len);
544	            type_str[len] = '\0';
545	
546	            Token name_tok = p->current;
547	            advance(p);
548	
549	            char full[128];
550	            snprintf(full, sizeof(full), "%s %.*s", type_str, name_tok.length, name_tok.start);
551	            ast_set_text(param, full, (int)strlen(full));
552	        } else {
553	            /* just an identifier (no type annotation) — type_tok was the param name */
554	            ast_set_text(param, type_tok.start, type_tok.length);
555	        }
556	    } else {
557	        Token name_tok = p->current;
558	        expect(p, TOK_IDENT);
559	        ast_set_text(param, name_tok.start, name_tok.length);
560	    }
561	    return param;
562	}
563	
564	static AstNode *parse_function_declaration(Parser *p) {
565	    Token kw = p->current; advance(p); /* consume 'function' */
566	    AstNode *decl = ast_new(ND_FUNCTION_DECL, kw.line);
567	
568	    Token name = p->current;
569	    expect(p, TOK_IDENT);
570	    ast_set_text(decl, name.start, name.length);
571	
572	    expect(p, TOK_LPAREN);
573	    if (!check(p, TOK_RPAREN)) {
574	        ast_add_child(decl, parse_parameter(p));
575	        while (match(p, TOK_COMMA)) {
576	            ast_add_child(decl, parse_parameter(p));
577	        }
578	    }
579	    expect(p, TOK_RPAREN);
580	    ast_add_child(decl, parse_block(p));
581	    return decl;
582	}
583	
584	/* ================================================================
585	   §5  If / elif / else
586	   ================================================================ */
587	
588	static AstNode *parse_if_statement(Parser *p) {
589	    Token kw = p->current; advance(p); /* 'if' */
590	    AstNode *ifn = ast_new(ND_IF, kw.line);
591	
592	    expect(p, TOK_LPAREN);
593	    ast_add_child(ifn, parse_expression(p));
594	    expect(p, TOK_RPAREN);
595	    ast_add_child(ifn, parse_block(p));
596	
597	    while (check(p, TOK_ELIF)) {
598	        advance(p);
599	        expect(p, TOK_LPAREN);
600	        ast_add_child(ifn, parse_expression(p));
601	        expect(p, TOK_RPAREN);
602	        ast_add_child(ifn, parse_block(p));
603	    }
604	
605	    if (check(p, TOK_ELSE)) {
606	        advance(p);
607	        ast_add_child(ifn, parse_block(p));
608	    }
609	    return ifn;
610	}
611	
612	/* ================================================================
613	   §4  For loop
614	   ================================================================ */
615	
616	static AstNode *parse_for_statement(Parser *p) {
617	    Token kw = p->current; advance(p); /* 'for' */
618	    AstNode *forn = ast_new(ND_FOR, kw.line);
619	
620	    expect(p, TOK_LPAREN);
621	    expect(p, TOK_LET);
622	    Token var = p->current;
623	    expect(p, TOK_IDENT);
624	    AstNode *var_node = ast_new(ND_IDENT, var.line);
625	    ast_set_text(var_node, var.start, var.length);
626	    ast_add_child(forn, var_node);
627	
628	    expect(p, TOK_IN);
629	    ast_add_child(forn, parse_expression(p));
630	    expect(p, TOK_RPAREN);
631	    ast_add_child(forn, parse_block(p));
632	    return forn;
633	}
634	
635	/* ================================================================
636	   §2  Block and Statements
637	   ================================================================ */
638	
639	static AstNode *parse_block(Parser *p) {
640	    Token lbrace = p->current;
641	    expect(p, TOK_LBRACE);
642	    AstNode *block = ast_new(ND_BLOCK, lbrace.line);
643	    while (!check(p, TOK_RBRACE) && !check(p, TOK_EOF)) {
644	        AstNode *stmt = parse_statement(p);
645	        if (stmt) ast_add_child(block, stmt);
646	    }
647	    expect(p, TOK_RBRACE);
648	    return block;
649	}
650	
651	static AstNode *parse_statement(Parser *p) {
652	    /* variable declaration */
653	    if (check(p, TOK_LET)) {
654	        advance(p);
655	        Token name = p->current;
656	        expect(p, TOK_IDENT);
657	        expect(p, TOK_EQ);
658	        AstNode *decl = ast_new(ND_VAR_DECL, name.line);
659	        ast_set_text(decl, name.start, name.length);
660	        ast_add_child(decl, parse_expression(p));
661	        expect(p, TOK_SEMICOLON);
662	        return decl;
663	    }
664	
665	    /* return */
666	    if (check(p, TOK_RETURN)) {
667	        Token kw = p->current; advance(p);
668	        AstNode *ret = ast_new(ND_RETURN, kw.line);
669	        if (!check(p, TOK_SEMICOLON)) ast_add_child(ret, parse_expression(p));
670	        expect(p, TOK_SEMICOLON);
671	        return ret;
672	    }
673	
674	    /* print */
675	    if (check(p, TOK_PRINT)) {
676	        Token kw = p->current; advance(p);
677	        AstNode *pr = ast_new(ND_PRINT, kw.line);
678	        ast_add_child(pr, parse_expression(p));
679	        expect(p, TOK_SEMICOLON);
680	        return pr;
681	    }
682	
683	    /* for */
684	    if (check(p, TOK_FOR)) return parse_for_statement(p);
685	
686	    /* if */
687	    if (check(p, TOK_IF))  return parse_if_statement(p);
688	
689	    /* assignment or expression statement
690	       We parse an expression, then check for assignment operators. */
691	    {
692	        AstNode *lhs = parse_postfix(p);
693	
694	        if (check(p, TOK_EQ)) {
695	            Token op = p->current; advance(p);
696	            AstNode *asgn = ast_new(ND_ASSIGN, op.line);
697	            ast_add_child(asgn, lhs);
698	            ast_add_child(asgn, parse_expression(p));
699	            expect(p, TOK_SEMICOLON);
700	            return asgn;
701	        }
702	
703	        if (check(p, TOK_PLUS_EQ)  || check(p, TOK_MINUS_EQ) ||
704	            check(p, TOK_STAR_EQ)  || check(p, TOK_SLASH_EQ)) {
705	            Token op = p->current; advance(p);
706	            AstNode *aug = ast_new(ND_AUG_ASSIGN, op.line);
707	            ast_set_text(aug, op.start, op.length);
708	            ast_add_child(aug, lhs);
709	            ast_add_child(aug, parse_expression(p));
710	            expect(p, TOK_SEMICOLON);
711	            return aug;
712	        }
713	
714	        /* finish as comparison (lhs may be just the start of a longer expr) */
715	        /* We already consumed postfix — wrap into comparison from there */
716	        /* Handle binary comparisons / additive on top of lhs */
717	        AstNode *expr = lhs;
718	
719	        /* additive continuation */
720	        while (check(p, TOK_PLUS) || check(p, TOK_MINUS)) {
721	            Token op = p->current; advance(p);
722	            AstNode *bin = ast_new(ND_BINARY, op.line);
723	            ast_set_text(bin, op.start, op.length);
724	            ast_add_child(bin, expr);
725	            ast_add_child(bin, parse_unary(p));
726	            expr = bin;
727	        }
728	        /* multiplicative was already consumed inside postfix/unary —
729	           but we entered via parse_postfix, not parse_multiplicative.
730	           Handle * and / continuation here. */
731	        while (check(p, TOK_STAR) || check(p, TOK_SLASH)) {
732	            Token op = p->current; advance(p);
733	            AstNode *bin = ast_new(ND_BINARY, op.line);
734	            ast_set_text(bin, op.start, op.length);
735	            ast_add_child(bin, expr);
736	            ast_add_child(bin, parse_unary(p));
737	            expr = bin;
738	        }
739	        /* comparison */
740	        if (check(p, TOK_EQ_EQ) || check(p, TOK_BANG_EQ) ||
741	            check(p, TOK_LT_EQ) || check(p, TOK_GT_EQ)   ||
742	            check(p, TOK_LT)    || check(p, TOK_GT)) {
743	            Token op = p->current; advance(p);
744	            AstNode *cmp = ast_new(ND_BINARY, op.line);
745	            ast_set_text(cmp, op.start, op.length);
746	            ast_add_child(cmp, expr);
747	            ast_add_child(cmp, parse_additive(p));
748	            expr = cmp;
749	        }
750	
751	        AstNode *stmt = ast_new(ND_EXPR_STMT, expr->line);
752	        ast_add_child(stmt, expr);
753	        expect(p, TOK_SEMICOLON);
754	        return stmt;
755	    }
756	}
757	
758	/* ================================================================
759	   §1  Top-level statements and program
760	   ================================================================ */
761	
762	static AstNode *parse_top_level(Parser *p) {
763	    /* element declaration */
764	    if (ident_is(&p->current, "element")) {
765	        AstNode *n = parse_element_declaration(p);
766	        expect(p, TOK_SEMICOLON);
767	        return n;
768	    }
769	
770	    /* compound declaration */
771	    if (ident_is(&p->current, "compound")) {
772	        AstNode *n = parse_compound_declaration(p);
773	        expect(p, TOK_SEMICOLON);
774	        return n;
775	    }
776	
777	    /* reaction declaration */
778	    if (ident_is(&p->current, "reaction")) {
779	        AstNode *n = parse_reaction_declaration(p);
780	        expect(p, TOK_SEMICOLON);
781	        return n;
782	    }
783	
784	    /* function declaration */
785	    if (check(p, TOK_FUNCTION)) {
786	        AstNode *n = parse_function_declaration(p);
787	        expect(p, TOK_SEMICOLON);
788	        return n;
789	    }
790	
791	    /* variable declaration */
792	    if (check(p, TOK_LET)) {
793	        advance(p);
794	        Token name = p->current;
795	        expect(p, TOK_IDENT);
796	        expect(p, TOK_EQ);
797	        AstNode *decl = ast_new(ND_VAR_DECL, name.line);
798	        ast_set_text(decl, name.start, name.length);
799	        ast_add_child(decl, parse_expression(p));
800	        expect(p, TOK_SEMICOLON);
801	        return decl;
802	    }
803	
804	    /* print */
805	    if (check(p, TOK_PRINT)) {
806	        Token kw = p->current; advance(p);
807	        AstNode *pr = ast_new(ND_PRINT, kw.line);
808	        ast_add_child(pr, parse_expression(p));
809	        expect(p, TOK_SEMICOLON);
810	        return pr;
811	    }
812	
813	    /* for statement — no trailing semicolon at top level (`;` optional after `}`) */
814	    if (check(p, TOK_FOR)) {
815	        AstNode *n = parse_for_statement(p);
816	        match(p, TOK_SEMICOLON); /* accept optional trailing `;` */
817	        return n;
818	    }
819	
820	    /* if statement — no trailing semicolon */
821	    if (check(p, TOK_IF)) return parse_if_statement(p);
822	
823	    /* expression or assignment statement */
824	    {
825	        AstNode *lhs = parse_postfix(p);
826	
827	        if (check(p, TOK_EQ)) {
828	            Token op = p->current; advance(p);
829	            AstNode *asgn = ast_new(ND_ASSIGN, op.line);
830	            ast_add_child(asgn, lhs);
831	            ast_add_child(asgn, parse_expression(p));
832	            expect(p, TOK_SEMICOLON);
833	            return asgn;
834	        }
835	
836	        if (check(p, TOK_PLUS_EQ)  || check(p, TOK_MINUS_EQ) ||
837	            check(p, TOK_STAR_EQ)  || check(p, TOK_SLASH_EQ)) {
838	            Token op = p->current; advance(p);
839	            AstNode *aug = ast_new(ND_AUG_ASSIGN, op.line);
840	            ast_set_text(aug, op.start, op.length);
841	            ast_add_child(aug, lhs);
842	            ast_add_child(aug, parse_expression(p));
843	            expect(p, TOK_SEMICOLON);
844	            return aug;
845	        }
846	
847	        /* expression statement — finish off higher-precedence levels */
848	        AstNode *expr = lhs;
849	        while (check(p, TOK_STAR) || check(p, TOK_SLASH)) {
850	            Token op = p->current; advance(p);
851	            AstNode *bin = ast_new(ND_BINARY, op.line);
852	            ast_set_text(bin, op.start, op.length);
853	            ast_add_child(bin, expr);
854	            ast_add_child(bin, parse_unary(p));
855	            expr = bin;
856	        }
857	        while (check(p, TOK_PLUS) || check(p, TOK_MINUS)) {
858	            Token op = p->current; advance(p);
859	            AstNode *bin = ast_new(ND_BINARY, op.line);
860	            ast_set_text(bin, op.start, op.length);
861	            ast_add_child(bin, expr);
862	            ast_add_child(bin, parse_unary(p));
863	            expr = bin;
864	        }
865	        if (check(p, TOK_EQ_EQ) || check(p, TOK_BANG_EQ) ||
866	            check(p, TOK_LT_EQ) || check(p, TOK_GT_EQ)   ||
867	            check(p, TOK_LT)    || check(p, TOK_GT)) {
868	            Token op = p->current; advance(p);
869	            AstNode *cmp = ast_new(ND_BINARY, op.line);
870	            ast_set_text(cmp, op.start, op.length);
871	            ast_add_child(cmp, expr);
872	            ast_add_child(cmp, parse_additive(p));
873	            expr = cmp;
874	        }
875	
876	        AstNode *stmt = ast_new(ND_EXPR_STMT, expr->line);
877	        ast_add_child(stmt, expr);
878	        expect(p, TOK_SEMICOLON);
879	        return stmt;
880	    }
881	}
882	
883	/* ================================================================
884	   Public API
885	   ================================================================ */
886	
887	void parser_init(Parser *p, Lexer *l) {
888	    p->lexer = l;
889	    advance(p); /* prime the lookahead */
890	}
891	
892	AstNode *parse_program(Parser *p) {
893	    AstNode *prog = ast_new(ND_PROGRAM, 1);
894	    while (!check(p, TOK_EOF)) {
895	        AstNode *node = parse_top_level(p);
896	        if (node) ast_add_child(prog, node);
897	        else {
898	            /* stuck — skip one token to avoid infinite loop */
899	            if (!check(p, TOK_EOF)) advance(p);
900	        }
901	    }
902	    return prog;
903	}
